import { Component, Element, Host, Listen, Prop, h } from "@stencil/core";
import retargetEvents from "react-shadow-dom-retarget-events";
import {
	addClassesOnLayers,
	arcLinkLabel,
	clickEvents,
	configSetup,
	setSize,
} from "../../donut-utils/utils";
import { renderPieChart } from "./RenderChart";

interface Legend {
	contains: boolean;
	anchor?: string;
}

interface RadialLabel {
	text: string;
	format: Function;
}

/**
 * @since 0.0.6
 * @status beta
 *
 */
@Component({
	tag: "hbr-donut",
	styleUrl: "./donut.scss",
	shadow: true,
})
export class HbrDonut {
	donutChart: HTMLElement;

	/** Chart configuration object. Refer to https://nivo.rocks/pie */
	@Prop({ mutable: true }) config: any;
	/** Chart size, small / medium / large */
	@Prop() size: string;
	/** Chart width */
	@Prop() width = "100%";
	/** Chart height */
	@Prop() height = "360px";
	/** Radial Label text and format in the center of Chart */
	@Prop() radialLabel: RadialLabel;
	/** Show tooltip on legend hover */
	@Prop() legendTooltip = true;

	@Listen("click", { passive: true })
	handleClick(evt) {
		const path = evt.path || evt.composedPath?.();
		if (path?.length) {
			clickEvents.call(this, path);
		}
	}

	@Element() private el: HTMLHbrDonutElement;

	otherItems: Array<Object>;
	_legend: Legend;
	hasLegends: boolean;
	rightLegend: boolean;
	partialLimited: boolean;
	total: number;

	componentDidLoad() {
		this.createChart();
		retargetEvents(this.el.shadowRoot);
		setTimeout(() => {
			addClassesOnLayers.call(this, "donut");
			/** make sure hide path(line) from LinkLabels except skip label items */
			arcLinkLabel(this.config, this.donutChart);
		}, 100);
	}

	componentShouldUpdate() {
		return this.createChart();
	}

	noLegendFn = (layers, legends) =>
		(!layers || !layers.includes("legends")) && (!legends || !legends.length);

	createChart() {
		const { config, size, donutChart } = this;
		configSetup.call(this, size, config);

		renderPieChart({
			el: donutChart,
			config,
		});
	}

	/** enableRadialLabels --
	 * nivo provide this as boolean but hbr wants only enable for the items with low value not all the items */
	render() {
		const { config, size } = this;
		if (config.legends === null) {
			config.legends = [];
		}
		const { legends, endAngle, startAngle } = config;
		const hasLegend =
			legends === undefined || (Array.isArray(legends) && 0 < legends?.length);
		this.hasLegends = hasLegend;
		this.rightLegend = Array.isArray(legends) && legends[0]?.anchor === "right";
		this.partialLimited = endAngle === 90 && Math.abs(startAngle) === endAngle;
		this.hasLegends = legends === undefined || legends.length;

		if (size) {
			const { width, height } = setSize.call(this, size, config);
			this.width = width;
			this.height = height;
		}

		this.el.style.width = this.width;
		this.el.style.height = this.height;
		const cls = `--hbr-chart --donut-chart${size ? ` --size-${size}` : ""}`;

		return (
			<Host>
				<div
					id="root"
					style={{ width: this.width, height: this.height }}
					ref={(el) => (this.donutChart = el)}
					class={cls}
				/>
			</Host>
		);
	}
}
